const ctaEndings = [
  'Ready to play? Jump in now — no download, no signup required!',
  'Play instantly in your browser, 100% free, on any device!',
  'No installs, no waiting — just click and start playing right away!',
  'Available free on desktop and mobile — start playing in seconds!'
];
function thumbHtml(g) {
  const img = getGameImg(g);
  const inner = img ? '<img src="' + img + '" alt="' + esc(g.name) + '" loading="lazy">' : '';
  const fb = '<div class="fb" style="' + (img ? 'display:none' : '') + '">' + (g.emoji || '🎮') + '</div>';
  const badge = g.featured ? '<span class="badge b-feat">⭐ Featured</span>' : (g.tag ? '<span class="badge ' + (g.tag === 'hot' ? 'b-hot' : 'b-new') + '">' + (g.tag === 'hot' ? '🔥 Hot' : '✨ New') + '</span>' : '');
  return '<div class="th th-grid ' + (!g.img ? (g.color || '') : '') + '">' + inner + fb + badge + '<div class="pmask"><div class="pbtn pbtn-sm">▶</div></div></div>';
}
function relatedGamesHtml(g, allGames) {
  const sameCat = allGames.filter(x => x.cat === g.cat && x.name !== g.name);
  const list = (sameCat.length >= 6 ? sameCat : allGames.filter(x => x.name !== g.name)).slice(0, 18);
  return list.map(r => {
    const ri = allGames.indexOf(r);
    return '<a class="gc" href="/game/' + slugify(r.name) + '/" onclick="openGame(' + ri + ');return false;">' + thumbHtml(r) + '<div class="gn">' + esc(r.name) + '</div></a>';
  }).join('');
}

function renderGamePage(slug) {
  const g = GAMES.find(x => slugify(x.name) === slug);
  if (!g) return null;

  const gIdx = GAMES.indexOf(g);
  const catPool = catDescs[g.cat] || ['Amazing free online game! Play instantly no download needed.'];
  const catD = catPool[gIdx % catPool.length];
  const cta = ctaEndings[gIdx % ctaEndings.length];
  const gameUrl = SITE_URL + '/game/' + slug + '/';
  const yr = new Date().getFullYear();
  const powerDesc = '🎮 Play ' + g.name + ' free online on PlayOnePixel! ' + (g.desc ? g.desc + ' ' : '') + catD + ' ' + cta;
  const powerKw = [
    g.name, g.name+' free', g.name+' online', g.name+' '+yr, g.name+' play now', g.name+' no download',
    g.name+' browser', g.name+' mobile', g.name+' unblocked', g.name+' free online', g.name+' play free',
    'play '+g.name, 'play '+g.name+' free', 'play '+g.name+' online',
    g.cat+' games '+yr, 'best '+g.cat+' games '+yr, 'free '+g.cat+' games', g.cat+' games online',
    'free online games '+yr, 'best free games '+yr, 'trending games '+yr, 'playonepixel '+g.name, 'playonepixel games'
  ].join(', ');
  const gImg = getGameImg(g) || (SITE_URL + '/og-image.png');
  const tags = [g.cat, 'Free', g.featured ? 'Featured' : (g.tag || 'Popular'), 'Browser Game'];
  const tagsHtml = [...new Set(tags)].filter(Boolean).map(t => '<span class="gptag">' + esc(t) + '</span>').join('');

  const schema = JSON.stringify([
    { '@context': 'https://schema.org', '@type': 'VideoGame', name: g.name, description: powerDesc, url: gameUrl, image: gImg, genre: [g.cat, 'Free Game', 'Browser Game'], applicationCategory: 'Game', operatingSystem: 'Any Browser', offers: { '@type': 'Offer', price: '0', priceCurrency: 'USD' }, isAccessibleForFree: true, isFamilyFriendly: true },
    { '@context': 'https://schema.org', '@type': 'BreadcrumbList', itemListElement: [
      { '@type': 'ListItem', position: 1, name: 'Home', item: SITE_URL + '/' },
      { '@type': 'ListItem', position: 2, name: g.cat, item: SITE_URL + '/?cat=' + g.cat },
      { '@type': 'ListItem', position: 3, name: g.name, item: gameUrl }
    ] }
  ]);

  const frameHtml = g.url
    ? '<iframe src="' + g.url + '" allowfullscreen allow="fullscreen;autoplay" style="width:100%;aspect-ratio:16/10;border:none;display:block;" loading="eager" title="' + esc(g.name) + '"></iframe>'
    : '<div class="gpnourl"><span>' + (g.emoji || '🎮') + '</span><h3>' + esc(g.name) + '</h3></div>';

  let out = TEMPLATE;
  out = out.replace(/<title>[^<]*<\/title>/, '<title>' + esc(g.name + ' - Play Free Online ' + yr + ' | Trending | No Download | PlayOnePixel') + '</title>');
  out = out.replace(/<meta name="description" content="[^"]*"\/>/, '<meta name="description" content="' + esc(powerDesc) + '"/>');
  out = out.replace(/<meta name="keywords" content="[\s\S]*?"\/>/, '<meta name="keywords" content="' + esc(powerKw) + '"/>');
  out = out.replace(/<link rel="canonical" href="[^"]*"\/>/, '<link rel="canonical" href="' + gameUrl + '"/>');
  out = out.replace(/<meta property="og:title" content="[^"]*"\/>/, '<meta property="og:title" content="' + esc(g.name) + ' - Play Free Online | PlayOnePixel 🎮"/>');
  out = out.replace(/<meta property="og:description" content="[^"]*"\/>/, '<meta property="og:description" content="' + esc(powerDesc) + '"/>');
  out = out.replace(/<meta property="og:image" content="[^"]*"\/>/, '<meta property="og:image" content="' + gImg + '"/>');
  out = out.replace(/<meta property="og:url" content="[^"]*"\/>/, '<meta property="og:url" content="' + gameUrl + '"/>');
  out = out.replace('</head>', '<script type="application/ld+json">' + schema + '</script>\n</head>');
  out = out.replace('<div id="homeView" class="view active">', '<div id="homeView" class="view" style="display:none">');
  out = out.replace('<footer>', '<footer style="display:none">');
  out = out.replace('<div id="gameView" class="view">', '<div id="gameView" class="view active" style="display:block">');
  out = out.replace('<h3 id="gpNUName">Game</h3>', '<h3 id="gpNUName">' + esc(g.name) + '</h3>');
  out = out.replace('<h2 id="gpName">Game</h2>', '<h2 id="gpName">' + esc(g.name) + '</h2>');
  out = out.replace('<span id="gpCat">cat</span>', '<span id="gpCat">' + esc(g.cat) + '</span>');
  out = out.replace('<div class="gpdesc" id="gpDesc"></div>', '<div class="gpdesc" id="gpDesc">' + esc(powerDesc) + '</div>');
  out = out.replace('<div class="gptags" id="gpTags"></div>', '<div class="gptags" id="gpTags">' + tagsHtml + '</div>');
  const iconHtml = getGameImg(g) ? '<img src="' + getGameImg(g) + '" style="width:100%;height:100%;object-fit:cover;border-radius:12px;" alt="' + esc(g.name) + '">' : (g.emoji || '🎮');
  out = out.replace('<div class="gpicon" id="gpIcon">🎮</div>', '<div class="gpicon" id="gpIcon">' + iconHtml + '</div>');
  out = out.replace(/<div class="gpframe" id="gpFrame">[\s\S]*?<\/div>\s*<\/div>\s*<div class="gpinfo">/, '<div class="gpframe" id="gpFrame">' + frameHtml + '</div>\n<div class="gpinfo">');
  out = out.replace('<div class="relgrid" id="relGrid"></div>', '<div class="relgrid" id="relGrid">' + relatedGamesHtml(g, GAMES) + '</div>');

  return out;
}

function renderSitemap() {
  const today = new Date().toISOString().split('T')[0];
  let urls = [`<url><loc>${SITE_URL}/</loc><lastmod>${today}</lastmod><changefreq>daily</changefreq><priority>1.0</priority></url>`];
  GAMES.forEach(g => {
    if (!g.name) return;
    urls.push(`<url><loc>${SITE_URL}/game/${slugify(g.name)}/</loc><lastmod>${today}</lastmod><changefreq>weekly</changefreq><priority>0.8</priority></url>`);
  });
  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls.join('\n')}
</urlset>`;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;

    if (path === '/sitemap.xml') {
      return new Response(renderSitemap(), {
        status: 200,
        headers: { 'Content-Type': 'application/xml; charset=utf-8' }
      });
    }

    // ═══ SINGLE SOURCE OF TRUTH: /games-data.json is generated live from the GAMES
    // array in THIS file. Add new games only here (in the GAMES const above) —
    // the live site's fetch('/games-data.json') call and the SEO game pages both
    // read from this same array automatically. No separate JSON file to edit. ═══
    if (path === '/games-data.json') {
      return new Response(JSON.stringify(GAMES), {
        status: 200,
        headers: {
          'Content-Type': 'application/json; charset=utf-8',
          'Cache-Control': 'no-cache'
        }
      });
    }

    const gameMatch = path.match(/^\/game\/([^\/]+)\/?$/);
    if (gameMatch) {
      const slug = gameMatch[1].toLowerCase();
      const html = renderGamePage(slug);
      if (html) {
        return new Response(html, {
          status: 200,
          headers: { 'Content-Type': 'text/html; charset=utf-8' }
        });
      }
      return new Response('<h1>Game not found</h1>', { status: 404, headers: { 'Content-Type': 'text/html' } });
    }

    return env.ASSETS.fetch(request);
  }
};
